#!/usr/bin/env python3
"""Hardware tests for ResetOdometry and ResetOdometryTo."""

import argparse
import json
import math
import sys
import threading
import time
from collections import deque
from dataclasses import dataclass
from typing import Callable, Deque, Tuple

import booster_robotics_sdk_python as br


@dataclass(frozen=True)
class Pose2D:
    x: float
    y: float
    theta: float


def normalize_angle(angle: float) -> float:
    return math.atan2(math.sin(angle), math.cos(angle))


def angle_error(actual: float, expected: float) -> float:
    return abs(normalize_angle(actual - expected))


class OdometerMonitor:
    def __init__(self, history_size: int = 200) -> None:
        self._condition = threading.Condition()
        self._samples: Deque[Tuple[int, Pose2D]] = deque(maxlen=history_size)
        self._sample_id = 0

    def callback(self, msg: br.Odometer) -> None:
        pose = Pose2D(float(msg.x), float(msg.y), float(msg.theta))
        with self._condition:
            self._sample_id += 1
            self._samples.append((self._sample_id, pose))
            self._condition.notify_all()

    def mark(self) -> int:
        with self._condition:
            return self._sample_id

    def wait_for_first_sample(self, timeout: float) -> Pose2D:
        deadline = time.monotonic() + timeout
        with self._condition:
            while not self._samples:
                remaining = deadline - time.monotonic()
                if remaining <= 0.0:
                    raise TimeoutError("No odometer message was received")
                self._condition.wait(remaining)
            return self._samples[-1][1]

    def wait_for_pose(
        self,
        expected: Pose2D,
        after_sample: int,
        timeout: float,
        position_tolerance: float,
        angle_tolerance: float,
        stable_samples: int,
    ) -> Pose2D:
        deadline = time.monotonic() + timeout
        with self._condition:
            while True:
                recent = [
                    pose for sample_id, pose in self._samples
                    if sample_id > after_sample
                ]
                if len(recent) >= stable_samples:
                    candidates = recent[-stable_samples:]
                    if all(
                        abs(pose.x - expected.x) <= position_tolerance
                        and abs(pose.y - expected.y) <= position_tolerance
                        and angle_error(pose.theta, expected.theta)
                        <= angle_tolerance
                        for pose in candidates
                    ):
                        return candidates[-1]

                remaining = deadline - time.monotonic()
                if remaining <= 0.0:
                    latest = self._samples[-1][1] if self._samples else None
                    raise TimeoutError(
                        f"Expected {expected}, latest odometer pose is {latest}"
                    )
                self._condition.wait(remaining)


class HardwareTestRunner:
    def __init__(self, args: argparse.Namespace) -> None:
        self.args = args
        self.monitor = OdometerMonitor()
        self.client = br.B1LocoClient()
        self.subscriber = br.B1OdometerStateSubscriber(self.monitor.callback)
        self.passed = 0
        self.failed = 0
        self.service_ready = False

    def initialize(self) -> None:
        br.ChannelFactory.Instance().Init(self.args.domain_id, self.args.iface)
        if self.args.robot_name:
            self.client.InitWithName(self.args.robot_name)
            self.subscriber.InitChannelWithName(self.args.robot_name)
        else:
            self.client.Init()
            self.subscriber.InitChannel()

        if not self.client.WaitForService(self.args.service_timeout_ms, True):
            raise RuntimeError("Loco RPC service is unavailable")
        self.service_ready = True

        initial_pose = self.monitor.wait_for_first_sample(self.args.timeout)
        print(f"Connected. Initial odometer pose: {initial_pose}")
        print(f"Odometer topic: {self.subscriber.GetChannelName()}")

    def close(self) -> None:
        self.subscriber.CloseChannel()

    def restore_zero_pose(self) -> None:
        if self.service_ready and not self.args.keep_final_pose:
            self.client.ResetOdometry()

    def run_pose_case(
        self,
        name: str,
        request: Callable[[], None],
        expected: Pose2D,
    ) -> None:
        print(f"\n[ RUN      ] {name}: expected={expected}")
        marker = self.monitor.mark()
        try:
            request()
            actual = self.monitor.wait_for_pose(
                expected=expected,
                after_sample=marker,
                timeout=self.args.timeout,
                position_tolerance=self.args.position_tolerance,
                angle_tolerance=self.args.angle_tolerance,
                stable_samples=self.args.stable_samples,
            )
        except Exception as exc:
            self.failed += 1
            print(f"[  FAILED  ] {name}: {exc}")
            return

        self.passed += 1
        print(f"[       OK ] {name}: actual={actual}")

    def run_invalid_request_case(self) -> None:
        name = "reject_invalid_pose"
        print(f"\n[ RUN      ] {name}")
        body = json.dumps({"x": None, "y": 0.0, "theta": 0.0})
        try:
            status = self.client.SendApiRequest(
                br.LocoApiId.kResetOdometry, body
            )
        except Exception as exc:
            self.failed += 1
            print(f"[  FAILED  ] {name}: RPC call failed unexpectedly: {exc}")
            return

        if status == 400:
            self.passed += 1
            print(f"[       OK ] {name}: server returned Bad Request (400)")
            return

        self.failed += 1
        print(f"[  FAILED  ] {name}: expected status 400, got {status}")

    def run(self) -> bool:
        target = Pose2D(
            self.args.target_x,
            self.args.target_y,
            normalize_angle(self.args.target_theta),
        )

        self.run_pose_case(
            "legacy_reset_to_zero",
            self.client.ResetOdometry,
            Pose2D(0.0, 0.0, 0.0),
        )
        self.run_pose_case(
            "reset_to_target_pose",
            lambda: self.client.ResetOdometryTo(
                target.x, target.y, target.theta
            ),
            target,
        )

        wrapped_theta = target.theta + 2.0 * math.pi
        self.run_pose_case(
            "normalize_target_theta",
            lambda: self.client.ResetOdometryTo(
                target.x, target.y, wrapped_theta
            ),
            target,
        )

        final_target = Pose2D(
            target.x - 0.4,
            target.y + 0.3,
            normalize_angle(target.theta - 0.5),
        )

        def submit_two_requests() -> None:
            self.client.ResetOdometryTo(
                target.x + 1.0,
                target.y - 1.0,
                target.theta + 1.0,
            )
            self.client.ResetOdometryTo(
                final_target.x,
                final_target.y,
                final_target.theta,
            )

        self.run_pose_case(
            "latest_request_wins",
            submit_two_requests,
            final_target,
        )
        self.run_invalid_request_case()

        if not self.args.keep_final_pose:
            self.run_pose_case(
                "cleanup_reset_to_zero",
                self.client.ResetOdometry,
                Pose2D(0.0, 0.0, 0.0),
            )

        print(f"\nResult: {self.passed} passed, {self.failed} failed")
        return self.failed == 0


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(
        description="Validate target-pose odometer reset on a robot"
    )
    parser.add_argument("iface", help="DDS network interface, for example eth0")
    parser.add_argument("--robot-name", default="")
    parser.add_argument("--domain-id", type=int, default=0)
    parser.add_argument("--target-x", type=float, default=1.25)
    parser.add_argument("--target-y", type=float, default=-0.75)
    parser.add_argument("--target-theta", type=float, default=0.6)
    parser.add_argument("--timeout", type=float, default=5.0)
    parser.add_argument("--service-timeout-ms", type=int, default=5000)
    parser.add_argument("--position-tolerance", type=float, default=0.08)
    parser.add_argument("--angle-tolerance", type=float, default=0.08)
    parser.add_argument("--stable-samples", type=int, default=3)
    parser.add_argument(
        "--keep-final-pose",
        action="store_true",
        help="Do not reset odometry to zero after the test",
    )
    return parser.parse_args()


def main() -> int:
    args = parse_args()
    runner = HardwareTestRunner(args)
    try:
        runner.initialize()
        return 0 if runner.run() else 1
    except KeyboardInterrupt:
        print("\nInterrupted")
        return 130
    except Exception as exc:
        print(f"Fatal error: {exc}", file=sys.stderr)
        return 2
    finally:
        try:
            runner.restore_zero_pose()
        except Exception as exc:
            print(f"Warning: final reset to zero failed: {exc}", file=sys.stderr)
        try:
            runner.close()
        except Exception:
            pass


if __name__ == "__main__":
    sys.exit(main())
